import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { documentService } from '../../services/documentService';
import { clientService } from '../../services/clientService';
import Swal from 'sweetalert2';

export const DocumentViewerImproved = () => {
  const { user } = useAuth();
  const [documents, setDocuments] = useState([]);
  const [filteredDocs, setFilteredDocs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [clients, setClients] = useState([]);
  
  // Filtros
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedClient, setSelectedClient] = useState('');
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());
  const [selectedType, setSelectedType] = useState('');

  const isSuperAdmin = user?.role === 'super_admin';
  const isAdmin = user?.role === 'admin';
  const isConsultor = user?.role === 'user';
  const isClient = user?.role === 'client';

  // Cargar clientes disponibles
  useEffect(() => {
    if (isSuperAdmin || isAdmin) {
      loadClients();
    }
  }, [user]);

  // Cargar documentos cuando cambian los filtros principales
  useEffect(() => {
    loadDocuments();
  }, [selectedClient, selectedYear, selectedType]);

  // Aplicar búsqueda cuando cambia el término
  useEffect(() => {
    applySearch();
  }, [searchTerm, documents]);

  const loadClients = async () => {
    try {
      const data = await clientService.getAll();
      setClients(data);
    } catch (error) {
      console.error('Error cargando clientes:', error);
    }
  };

  const loadDocuments = async () => {
    try {
      setLoading(true);
      let docs = [];

      if (isSuperAdmin || isAdmin) {
        if (selectedClient) {
          // Si seleccionó cliente: mostrar todos sus documentos
          docs = await documentService.getClientAllDocuments(
            selectedClient,
            { year: selectedYear }
          );
        } else {
          // Sin cliente: mostrar solo públicos
          docs = await documentService.getPublic({
            year: selectedYear,
          });
        }
      } else if (isConsultor) {
        // Consultor: sus documentos + públicos
        const allDocs = await documentService.getAll({
          year: selectedYear,
        });
        
        docs = allDocs.filter(
          doc => doc.is_public || doc.uploaded_by._id === user._id
        );
      } else if (isClient) {
        // Cliente: sus documentos privados + públicos
        const allDocs = await documentService.getAll({
          year: selectedYear,
        });
        
        docs = allDocs.filter(
          doc => doc.is_public || 
                  (doc.client_id && doc.client_id._id === user.client_id)
        );
      }

      setDocuments(docs);
    } catch (error) {
      console.error('Error cargando documentos:', error);
      Swal.fire('Error', 'No se pudieron cargar los documentos', 'error');
    } finally {
      setLoading(false);
    }
  };

  const applySearch = () => {
    let filtered = documents;

    // Filtrar por búsqueda
    if (searchTerm.trim()) {
      const term = searchTerm.toLowerCase();
      filtered = filtered.filter(doc =>
        doc.title.toLowerCase().includes(term) ||
        doc.description?.toLowerCase().includes(term) ||
        doc.file_name.toLowerCase().includes(term)
      );
    }

    // Filtrar por tipo si está seleccionado
    if (selectedType) {
      filtered = filtered.filter(doc => doc.document_type === selectedType);
    }

    setFilteredDocs(filtered);
  };

  const handleDownload = async (doc) => {
    try {
      const blob = await documentService.download(doc._id);
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = doc.file_name;
      document.body.appendChild(link);
      link.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(link);
    } catch (error) {
      Swal.fire('Error', 'No se pudo descargar el archivo', 'error');
    }
  };

  const handleDelete = async (docId) => {
    const result = await Swal.fire({
      title: '¿Eliminar documento?',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#dc2626',
      confirmButtonText: 'Sí, eliminar',
    });

    if (result.isConfirmed) {
      try {
        await documentService.delete(docId);
        await loadDocuments();
        Swal.fire('Éxito', 'Documento eliminado', 'success');
      } catch (error) {
        Swal.fire('Error', 'No se pudo eliminar el documento', 'error');
      }
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h2 className="text-2xl font-bold text-gray-900">📄 Documentos</h2>
        <p className="text-sm text-gray-600 mt-1">
          {selectedClient 
            ? `Documentos de ${clients.find(c => c._id === selectedClient)?.company_name}`
            : isSuperAdmin || isAdmin
            ? 'Documentos Públicos - Selecciona un cliente para ver sus privados'
            : 'Tus documentos y archivos públicos'}
        </p>
      </div>

      {/* Filtros */}
      <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 space-y-4">
        {/* Búsqueda */}
        <div className="relative">
          <input
            type="text"
            placeholder="🔍 Buscar por título, descripción o archivo..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full px-4 py-2 pl-10 border rounded-lg focus:ring-2 focus:ring-blue-500"
          />
        </div>

        {/* Grid de filtros */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-3">
          {/* Cliente */}
          {(isSuperAdmin || isAdmin) && (
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Cliente
              </label>
              <select
                value={selectedClient}
                onChange={(e) => setSelectedClient(e.target.value)}
                className="w-full px-3 py-2 border rounded-lg text-sm"
              >
                <option value="">📊 Documentos Públicos</option>
                {clients.map(c => (
                  <option key={c._id} value={c._id}>
                    {c.company_name}
                  </option>
                ))}
              </select>
            </div>
          )}

          {/* Año */}
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">
              Año
            </label>
            <select
              value={selectedYear}
              onChange={(e) => setSelectedYear(parseInt(e.target.value))}
              className="w-full px-3 py-2 border rounded-lg text-sm"
            >
              {[2024, 2023, 2022, 2021].map(year => (
                <option key={year} value={year}>{year}</option>
              ))}
            </select>
          </div>

          {/* Tipo */}
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">
              Tipo
            </label>
            <select
              value={selectedType}
              onChange={(e) => setSelectedType(e.target.value)}
              className="w-full px-3 py-2 border rounded-lg text-sm"
            >
              <option value="">Todos</option>
              <option value="report">📊 Reporte</option>
              <option value="certification">✓ Certificación</option>
              <option value="manual">📖 Manual</option>
              <option value="permit">📜 Permiso</option>
            </select>
          </div>

          {/* Contador */}
          <div className="flex items-end">
            <div className="bg-white px-3 py-2 rounded-lg text-sm font-semibold w-full">
              {filteredDocs.length} documentos
            </div>
          </div>
        </div>
      </div>

      {/* Lista */}
      {loading ? (
        <div className="text-center py-12">
          <div className="animate-spin text-blue-600 text-3xl mb-2">⏳</div>
          <p className="text-gray-600">Cargando...</p>
        </div>
      ) : filteredDocs.length === 0 ? (
        <div className="bg-gray-50 border border-gray-200 rounded-lg p-12 text-center">
          <div className="text-4xl mb-2">📋</div>
          <p className="text-gray-600 font-semibold">No hay documentos</p>
          <p className="text-sm text-gray-500">Intenta con otros filtros</p>
        </div>
      ) : (
        <div className="space-y-3">
          {filteredDocs.map(doc => (
            <div
              key={doc._id}
              className="bg-white border border-gray-200 rounded-lg p-4 hover:shadow-lg transition-all"
            >
              <div className="flex items-start justify-between gap-4">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-xl">
                      {doc.document_type === 'report' ? '📊' :
                       doc.document_type === 'certification' ? '✓' :
                       doc.document_type === 'manual' ? '📖' : '📜'}
                    </span>
                    <h3 className="font-bold text-gray-900 truncate">
                      {doc.title}
                    </h3>
                    {doc.is_public && (
                      <span className="text-xs bg-green-100 text-green-700 px-2 py-1 rounded">
                        🌍 Público
                      </span>
                    )}
                  </div>
                  
                  {doc.description && (
                    <p className="text-sm text-gray-600 line-clamp-1 mb-2">
                      {doc.description}
                    </p>
                  )}
                  
                  <div className="flex flex-wrap gap-2 text-xs text-gray-500">
                    {doc.client_id && (
                      <span>👤 {doc.client_id.company_name}</span>
                    )}
                    <span>📅 {new Date(doc.created_at).toLocaleDateString('es-ES')}</span>
                    <span>💾 {(doc.file_size / 1024 / 1024).toFixed(2)} MB</span>
                  </div>
                </div>

                <div className="flex gap-2 flex-shrink-0">
                  <button
                    onClick={() => handleDownload(doc)}
                    className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 text-sm"
                  >
                    ⬇️ Descargar
                  </button>
                  {(isAdmin || doc.uploaded_by._id === user._id) && (
                    <button
                      onClick={() => handleDelete(doc._id)}
                      className="px-3 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 text-sm"
                    >
                      🗑️
                    </button>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default DocumentViewerImproved;
